{
  "name": "@srnoob2570/opencode-go-models",
  "version": "0.1.0",
  "description": "opencode 2.x plugin: keep the OpenCode Go model catalog in sync with the live provider registry",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/srnoob2570/opencode-go-models.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-go",
    "provider",
    "models"
  ],
  "main": "./plugin/index.ts",
  "exports": {
    ".": "./plugin/index.ts",
    "./server": "./plugin/index.ts"
  },
  "files": [
    "plugin/catalog.ts",
    "plugin/index.ts",
    "plugin/models.ts"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "^1.4.0",
    "@types/node": "^24.0.0",
    "typescript": "5.9.3"
  }
}

// opencode 2.x entry: keep the OpenCode Go model set aligned with the live
// provider registry. models.dev lags behind that registry, so a model added or
// retired upstream can stay missing from `/models` until OpenCode ships a new
// catalog; this plugin fetches the public list at startup and lets the live set
// define availability.
//
// Contract: silent degradation — a moved/missing plugin API retires the
// feature, never the host's boot. The transform is registered only after the
// registry loads, because registering it TAKES OWNERSHIP of the provider's
// model set (models.dev entries stop being merged); on failure nothing is
// registered and the host's models.dev catalog stays alive untouched.
import {
  fetchLive,
  LIVE_URL,
  PROVIDER_ID,
  type LiveModel,
  type PluginOpts,
} from "./catalog.ts";
import { toModelRecord, type ModelRecord } from "./models.ts";

/** The slice of the opencode 2.x PluginContext this module touches. */
interface PluginContext {
  options?: Record<string, unknown>;
  provider?: {
    transform?: (cb: (draft: ProviderDraft) => unknown) => unknown;
  };
}

/** The slice of the provider draft the transform receives. */
export interface ProviderDraft {
  get?: (id: string) =>
    | {
        provider?: unknown;
        models?: ReadonlyMap<string, ModelRecord> | Record<string, ModelRecord>;
      }
    | null
    | undefined;
  models?: {
    set?: (providerID: string, models: ModelRecord[]) => unknown;
  };
}

const asString = (v: unknown): string | undefined =>
  typeof v === "string" ? v : undefined;
const asNumber = (v: unknown): number | undefined =>
  typeof v === "number" ? v : undefined;

function existingModel(models: unknown, id: string): ModelRecord | undefined {
  if (typeof models !== "object" || models === null) return undefined;
  const get = (models as { get?: unknown }).get;
  if (typeof get === "function") {
    return (get as (id: string) => ModelRecord | undefined).call(models, id);
  }
  return (models as Record<string, ModelRecord>)[id];
}

/**
 * Transform body, exported for tests. The live list owns the set: retired
 * models disappear and new ones are built from live metadata. Known models
 * keep the package/endpoint/variants the host materialized. A throw here must
 * never break the host's boot.
 */
export function applyModels(
  draft: ProviderDraft | null | undefined,
  live: LiveModel[],
): void {
  try {
    if (typeof draft?.get !== "function") return;
    const record = draft.get(PROVIDER_ID);
    if (!record) return;

    const models = live.map((model) =>
      toModelRecord(model, existingModel(record.models, model.id)),
    );
    draft.models?.set?.(PROVIDER_ID, models);
  } catch {
    /* one bad transform call must never break the host's boot */
  }
}

async function setup(ctx: unknown): Promise<void> {
  try {
    const c = ctx as PluginContext | null | undefined;
    const provider = c?.provider;
    if (typeof provider?.transform !== "function") return;

    const options = (c?.options ?? {}) as Record<string, unknown>;
    const opts: PluginOpts = {
      modelsUrl: asString(options.modelsUrl),
      timeoutMs: asNumber(options.timeoutMs),
    };
    const live = await fetchLive(
      opts.modelsUrl ?? LIVE_URL,
      opts.timeoutMs ?? 5000,
    );
    if (!live || live.length === 0) return;

    await provider.transform((draft: ProviderDraft) =>
      applyModels(draft, live),
    );
  } catch {
    /* silent degradation: a host must still boot the plugin cleanly */
  }
}

export default {
  id: "opencode-go-models",
  setup,
};
